    t0 = time.process_time()
    rng = np.random.default_rng(1234)
    deadline = t0 + budget_seconds * 0.85

    best = None
    bestC = np.inf

    def consider(h):
        nonlocal best, bestC
        h = np.asarray(h, dtype=float)
        if h.size < 1 or h.size > 30000:
            return
        if not np.all(np.isfinite(h)) or h.sum() <= 0:
            return
        c = _C(h)
        if c < bestC:
            bestC = c
            best = h.copy()

    if start is not None:
        consider(start)

    # Candidate initial bumps
    for N in (200, 400, 800, 1500):
        x = (np.arange(N) + 0.5) / N
        for p in (0.5, 1.0, 1.5, 2.0, 3.0):
            consider(np.sin(np.pi * x) ** p)
        consider(1.0 - (2 * x - 1) ** 2)
        consider(np.exp(-((x - 0.5) / 0.15) ** 2))

    if best is None:
        best = np.ones(50)
        bestC = _C(best)

    # Coordinate-wise multiplicative hill climb on the actual N.
    # Key change: optimize each coordinate exactly via a cheap local
    # perturbation, then refine with smooth multi-coordinate moves.
    def refine(h, deadline, iters):
        h = h.copy()
        c = _C(h)
        n = h.size
        steps = [0.2, 0.1, 0.05, 0.02, 0.01, 0.005, 0.002, 0.001]
        for st in steps:
            for it in range(iters):
                if time.process_time() > deadline:
                    return h, c
                g = h.copy()
                mode = rng.integers(0, 3)
                if mode == 0:
                    k = max(1, int(n * 0.02))
                    idx = rng.integers(0, n, size=k)
                    g[idx] *= (1.0 + st * rng.standard_normal(k))
                elif mode == 1:
                    # smooth bump perturbation
                    k = max(1, int(n * 0.1))
                    idx = rng.integers(0, n, size=k)
                    g[idx] += st * h.max() * rng.standard_normal(k)
                else:
                    # single coordinate
                    idx = rng.integers(0, n)
                    g[idx] *= (1.0 + st * rng.standard_normal())
                g = np.maximum(g, 0.0)
                if g.sum() <= 0:
