def _resample(s, N):
    s = np.asarray(s, dtype=float)
    if s.size == N:
        return s.copy()
    idx = np.linspace(0, s.size, N, endpoint=False).astype(int)
    return s[idx]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    rng = np.random.default_rng(987654321)

    best_h = None
    best_C = np.inf

    # Multiple resolutions: coarse for structure, then refine.
    # Build candidate pool from start + simple shapes at each N.
    Ns = [256, 384, 512, 768, 1024]

    # Initial shapes at each N to seed
    for N in Ns:
        if time.process_time() > deadline:
            break
        x = np.linspace(-0.5, 0.5, N)
        # exponential ramps
        for lam in np.linspace(-6.0, 6.0, 25):
            h = np.exp(lam * x)
            c = _C(h)
            if c < best_C:
                best_C, best_h = c, h.copy()
        # linear ramps
        for a in np.linspace(-2.0, 2.0, 21):
            h = np.maximum(0.0, 1.0 + a * x)
            if h.sum() > 0:
                c = _C(h)
                if c < best_C:
                    best_C, best_h = c, h.copy()
        # two-level step shapes
        for p in np.linspace(0.1, 0.9, 17):
            k = max(1, min(N - 1, int(round(p * N))))
            for r in np.logspace(-1, 1, 11):
                h = np.ones(N)
                h[k:] = r
                c = _C(h)
                if c < best_C:
                    best_C, best_h = c, h.copy()
        # start resampled
        if start is not None:
            hs = _resample(start, N)
            if hs.sum() > 0:
                c = _C(hs)
                if c < best_C:
                    best_C, best_h = c, hs.copy()

    if best_h is None:
        best_h = np.ones(512)
        best_C = _C(best_h)

    # Coordinate descent / local perturbation search on a chosen N.
    # Try to improve by upsampling and perturbing.
    def refine(h, N, iters, deadline, step_scale):
        h = _resample(h, N)
        c = _C(h)
        n = N
        for _ in range(iters):
            if time.process_time() > deadline:
                break
            # random block perturbation
            i = rng.integers(0, n)
            w = rng.integers(1, max(2, n // 8))
            j = min(n, i + w)
            factor = np.exp(rng.normal(0, step_scale))
            h2 = h.copy()
            h2[i:j] *= factor
            s = h2.sum()
            if s <= 0:
                continue
            c2 = _C(h2)
            if c2 < c:
                h, c = h2, c2
        return h, c

    # Iteratively refine at increasing resolution
    for N in [512, 768, 1024, 1536, 2048]:
        if time.process_time() > deadline:
            break
        iters = 200 if N <= 1024 else 100
        h2, c2 = refine(best_h, N, iters, deadline, 0.15)
        if c2 < best_C:
            best_C, best_h = c2, h2.copy()
        # smaller steps
        h2, c2 = refine(best_h, N, iters, deadline, 0.05)
        if c2 < best_C:
            best_C, best_h = c2, h2.copy()

    # Additional random restarts at best N
    Nbest = best_h.size
    while time.process_time() < deadline:
        # perturb current best
        h2 = best_h.copy()
        for _ in range(5):
            i = rng.integers(0, Nbest)
            w = rng.integers(1, max(2, Nbest // 16))
            j = min(Nbest, i + w)
            h2[i:j] *= np.exp(rng.normal(0, 0.1))
        if h2.sum() <= 0:
            continue
        c2 = _C(h2)
        if c2 < best_C:
            best_C, best_h = c2, h2.copy()

    print("best C = %.6f, N = %d, cpu %.2f s" % (best_C, best_h.size, time.process_time() - t0))
    return best_h

