def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _convolve_max(h):
    """Return max of self-convolution, computed via FFT for speed."""
    n = len(h)
    L = 2 * n - 1
    # next power of 2
    m = 1
    while m < L:
        m <<= 1
    f = np.fft.rfft(h, m)
    conv = np.fft.irfft(f * f, m)[:L]
    return np.max(conv)


def _Cfast(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * _convolve_max(h) / (s * s)


