                h = s.copy()
            else:
                x_old = np.linspace(0, 1, s.size)
                x_new = np.linspace(0, 1, N)
                h = np.interp(x_new, x_old, s)
            h = np.maximum(h, 0.0)
        else:
            h = np.ones(N)
    else:
        x = np.linspace(-1, 1, N)
        h = np.exp(-3.0 * x * x)

