            x = np.linspace(-1, 1, N)
            cand = np.exp(-rng.uniform(1.0, 6.0) * x * x) * (1.0 + 0.2 * rng.standard_normal(N))
            cand = np.maximum(cand, 0.0)
            if cand.sum() > 0:
                cand = cand / cand.sum()
                cur = cand.copy()
                curC = _Cfast(cur)
                step = 0.2
                while time_left() and step > 1e-4:
                    improved = False
                    idxs = rng.permutation(N)
                    for i in idxs:
                        if not time_left():
                            break
                        old = cur[i]
