                            bl = nv
                    cur[i] = bl
                    if blc < curC - 1e-13:
                        curC = blc
                        improved = True
                if not improved:
                    step *= 0.5
            if curC < best_C - 1e-13:
                best_C = curC
                best_h = cur.copy()

