            blc = c
            for mult in (1.0 + step, 1.0 - step):
                nv = old * mult
                if nv < 0:
                    nv = 0.0
                h[i] = nv
                cc = _Cfft(h)
                if cc < blc - 1e-13:
                    blc = cc
                    bl = nv
            h[i] = bl
            if blc < c - 1e-13:
                c = blc
                improved = True
        if not improved:
            step *= 0.5
    return h, c


