    base = base / base.sum()
    best = base.copy()
    bestC = _C(best)
    print("start C = %.6f, N = %d" % (bestC, best.size))

    # Progressive refinement: upsample and polish with basin hopping
    Nschedule = [512, 768, 1024, 1536, 2048, 2560, 3072, 4096]
    for N in Nschedule:
        if time.process_time() > deadline:
            break
        h = _resample(best, N)
        h = h / h.sum()
        c = _Cfft(h)
        # Polish
        h, c = _refine(h, 200, deadline, rng, 0.15)
        h, c = _refine(h, 200, deadline, rng, 0.05)
        # Basin hopping rounds
        for _ in range(4):
            if time.process_time() > deadline:
