            cand, cc = _refine(cand, 100, deadline, rng, 0.1)
            if cc < c - 1e-10:
                h, c = cand, cc
        if c < bestC - 1e-10:
            bestC, best = c, h.copy()
        print("N=%d C=%.6f best=%.6f cpu=%.1f" % (N, c, bestC, time.process_time() - t0))

    # Intensive final search at the best resolution found
    Nbest = best.size
    while time.process_time() < deadline:
        # perturb and polish
        sigma = 0.05 + 0.1 * rng.random()
        cand = best * (1.0 + sigma * rng.standard_normal(Nbest))
        cand = np.maximum(cand, 0.0)
        if cand.sum() <= 0:
            continue
        cand = cand / cand.sum()
        cand, cc = _refine(cand, 100, deadline, rng, 0.08)
        if cc < bestC - 1e-12:
            bestC, best = cc, cand.copy()
            print("improved C=%.6f cpu=%.1f" % (bestC, time.process_time() - t0))

    print("final C = %.6f, N = %d, cpu %.2f s" % (bestC, best.size, time.process_time() - t0))
    return np.maximum(best, 0.0)

