    return np.convolve(h, ker, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    rng = np.random.default_rng(987654321)

    if start is not None and np.asarray(start).size > 0:
        base = np.asarray(start, dtype=float)
    else:
        base = np.ones(2048)

    # Work at moderate N; the optimum shape is smooth, N=2048 is plenty
    N = 2048
    h = _resample(base, N)
    h = np.maximum(h, 0)
    c = _C_fft(h)
    best_h = h.copy()
    best_C = c
