            factor = float(np.exp(rng.normal(0, step_scale)))
            h2 = h.copy()
            h2[i:j] *= factor
            h, c = try_update(h, c, h2)
        if c < best_C:
            best_C, best_h = c, h.copy()
        print("blk step=%.4f C=%.6f cpu=%.2f" % (step_scale, c, time.process_time() - t0))

