            if c < best_C:
                best_C, best_h = c, h.copy()
        print("sym C=%.6f cpu=%.2f" % (c, time.process_time() - t0))

    # Phase 4: multi-scale direct optimization of a coarse representation.
    # Parametrize by M smooth basis values, upsample, refine.
    if time.process_time() < deadline:
