                    if c2 < cg:
                        g, cg = g2, c2
                        if c2 < best_C:
                            best_C, best_h = c2, h2.copy()
            print("coarse M=%d C=%.6f cpu=%.2f" % (M, best_C, time.process_time() - t0))

