    best_h = np.maximum(np.asarray(best_h, dtype=float), 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(N)
    exact = _C(best_h)
    print("final C=%.6f (fft %.6f) N=%d cpu=%.2f" % (exact, best_C, best_h.size, time.process_time() - t0))
    return best_h

