    f = np.fft.rfft(h, m)
    conv = np.fft.irfft(f * f, m)[:L]
    return 2.0 * n * np.max(conv) / (s * s)


def _conv(h):
    n = h.size
    L = 2 * n - 1
    m = 1
    while m < L:
        m <<= 1
    f = np.fft.rfft(h, m)
    return np.fft.irfft(f * f, m)[:L]


def _resample(s, N):
    s = np.asarray(s, dtype=float)
    if s.size == N:
        return s.copy()
    x_old = np.linspace(0, 1, s.size)
    x_new = np.linspace(0, 1, N)
    return np.interp(x_new, x_old, s)


def _refine(h, iters, deadline, rng, step0=0.2):
    """Coordinate descent with multiplicative steps; returns (h, C)."""
    n = h.size
    h = h.copy()
    c = _Cfft(h)
    step = step0
    while step > 1e-4 and time.process_time() < deadline:
        improved = False
        idxs = rng.permutation(n)
        for i in idxs:
            if time.process_time() > deadline:
                return h, c
            old = h[i]
            bl = old
            blc = c
            for mult in (1.0 + step, 1.0 - step):
                nv = old * mult
                if nv < 0:
                    nv = 0.0
                h[i] = nv
                cc = _Cfft(h)
                if cc < blc - 1e-13:
                    blc = cc
                    bl = nv
            h[i] = bl
            if blc < c - 1e-13:
                c = blc
                improved = True
        if not improved:
            step *= 0.5
    return h, c


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88
    rng = np.random.default_rng(20240607)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            base = np.maximum(s, 0.0)
        else:
            base = np.ones(1024)
    else:
        x = np.linspace(-1, 1, 1024)
        base = np.exp(-3.0 * x * x)

    base = base / base.sum()
    best = base.copy()
    bestC = _C(best)
    print("start C = %.6f, N = %d" % (bestC, best.size))

    # Try finer grids: 2048 then 4096
    for Nbest in (2048, 4096):
        if time.process_time() > deadline:
            break
        h = _resample(best, Nbest)
        h = h / h.sum()
        # capped refine sweeps
        if Nbest == 2048:
            h, c = _refine(h, 200, deadline, rng, 0.05)
            if time.process_time() < deadline:
                h, c = _refine(h, 200, deadline, rng, 0.02)
        else:
            h, c = _refine(h, 200, deadline, rng, 0.02)
        if c < bestC - 1e-10:
            bestC, best = c, h.copy()
        print("N=%d C=%.6f best=%.6f cpu=%.1f" % (Nbest, c, bestC, time.process_time() - t0))

        # interval perturbation loop at this N
        while time.process_time() < deadline:
            conv = _conv(best)
            M = conv.max()
            active = np.where(conv >= M * 0.995)[0]
            if active.size == 0:
                active = np.array([np.argmax(conv)])
            k = int(active[rng.integers(0, active.size)])
            W = int(rng.integers(5, 30))
            center = k / 2.0 + rng.normal(0, W / 4.0)
            lo = int(max(0, np.floor(center - W)))
            hi = int(min(Nbest, np.ceil(center + W) + 1))
            if hi <= lo:
                continue
            sigma = 0.1 + 0.4 * rng.random()
            cand = best.copy()
            seg = slice(lo, hi)
            cand[seg] = cand[seg] * (1.0 + sigma * rng.standard_normal(hi - lo))
            cand = np.maximum(cand, 0.0)
            if cand.sum() <= 0:
                continue
            cand = cand / cand.sum()
            cand, cc = _refine(cand, 100, deadline, rng, 0.08)
            if cc < bestC - 1e-12:
                bestC, best = cc, cand.copy()
                print("improved C=%.6f cpu=%.1f" % (bestC, time.process_time() - t0))

    # Final exact-C selection among candidates
    print("final C = %.6f, N = %d, cpu %.2f s" % (bestC, best.size, time.process_time() - t0))
    return np.maximum(best, 0.0)

import numpy as np
import time


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    n = h.size
    return 2.0 * n * np.max(np.convolve(h, h)) / (s * s)


def _fft_conv(h):
    n = h.size
    L = 2 * n - 1
    m = 1
    while m < L:
        m <<= 1
    F = np.fft.rfft(h, m)
    return np.fft.irfft(F * F, m)[:L]


def _Cfft(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    n = h.size
    return 2.0 * n * np.max(_fft_conv(h)) / (s * s)


def _resample(s, N):
    s = np.asarray(s, dtype=float)
    if s.size == N:
        return s.copy()
    x_old = np.linspace(0.0, 1.0, s.size)
    x_new = np.linspace(0.0, 1.0, N)
    return np.interp(x_new, x_old, s)


def _polish(h, deadline, rng, step0=0.15, passes=8, tol=1e-14):
    """Multiplicative coordinate descent with exact incremental conv updates."""
    h = h.copy()
    n = h.size
    L = 2 * n - 1
    s = h.sum()
    if s <= 0:
        return h, np.inf
    conv = _fft_conv(h)
    step = step0
    for _ in range(passes):
        if time.process_time() > deadline:
            break
        improved = False
        order = rng.permutation(n)
        for i in order:
            if time.process_time() > deadline:
                return h, _Cfft(h)
            old = h[i]
            if old <= 0:
                continue
            # Precompute the two shift contributions once
            # shift+i affects k in [i, i+n)
            # shift-i affects k in [0, n-i) using h[i-k]
            nsh = n - i
            kk = np.arange(0, min(i + 1, n - i))
            hi_part = h[kk.size - 1::-1][:kk.size] if kk.size else np.array([])
            # hi_part[m] = h[i - kk[m]]
            base_max = conv.max()
            best_v = old
            best_delta = 0.0
            best_c = 2.0 * n / (s * s) * base_max
            for mult in (1.0 + step, 1.0 - step):
                nv = old * mult
                if nv < 0:
                    nv = 0.0
                delta = nv - old
                if delta == 0.0:
                    continue
                s2 = s + delta
                if s2 <= 0:
                    continue
                # Compute candidate max on the affected window only.
                # k in [0, n-i) union [i, i+n) union {2i}
                # Build combined affected index set:
                #   region A: [0, min(L, n-i))  (shift-i)
                #   region B: [i, min(L, i+n))  (shift+i)
                #   plus {2i}
                cand_vals = []
                # shift+i part
                segB = conv[i:i + n] + delta * h
                cand_vals.append(segB)
                # shift-i part (only where not overlapping B, and including self)
                # For k in [0, n-i): conv[k] + delta*h[i-k]
                if nsh > 0:
                    segA = conv[0:nsh].copy()
                    m2 = min(kk.size, nsh)
                    segA[:m2] += delta * hi_part[:m2]
                    # if 2i in [0,nsh) it's inside A too; combine carefully:
                    if 2 * i < nsh and 2 * i < L:
                        segA[2 * i] += delta * delta
                    cand_vals.append(segA)
                elif 2 * i < L:
                    cand_vals.append(np.array([conv[2 * i] + delta * delta]))
                if 2 * i < L and not (2 * i < nsh):
                    cand_vals.append(np.array([conv[2 * i] + delta * delta]))
                # max outside affected: compute from conv by masking
                # Build a boolean mask of untouched indices for accuracy:
                # untouched = complement of (A ∪ B ∪ {2i})
                # For speed, approximate by using global max of untouched region:
                # Since affected region is small, just recompute full max using
                # the modified conv for correctness but only on candidate max.
                # To stay exact, build full candidate conv when needed.
                # We use a shortcut: compute max over untouched using np.delete-like.
                # For clarity: reconstruct max via masking.
                # Build mask
                mask = np.ones(L, dtype=bool)
                mask[0:nsh] = False
                mask[i:i + n] = False
                if 2 * i < L:
                    mask[2 * i] = False
                if mask.any():
                    untouched_max = conv[mask].max()
                else:
                    untouched_max = -np.inf
                cand_max = untouched_max
                for v in cand_vals:
                    if v.size:
                        m = v.max()
                        if m > cand_max:
                            cand_max = m
                cc = 2.0 * n / (s2 * s2) * cand_max
                if cc < best_c - tol:
                    best_c = cc
                    best_v = nv
                    best_delta = delta
            if best_v != old:
                # apply the winning change to conv
                delta = best_delta
                # shift+i
                conv[i:i + n] += delta * h
                # shift-i
                if nsh > 0:
                    m2 = min(kk.size, nsh)
                    conv[0:m2] += delta * hi_part[:m2]
                if 2 * i < L:
                    conv[2 * i] += delta * delta
                h[i] = best_v
                s += delta
                improved = True
        if not improved:
            step *= 0.5
            if step < 2e-4:
                break
    return h, _Cfft(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88
    rng = np.random.default_rng(987654321)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size and s.sum() > 0:
            base = np.maximum(s, 0.0)
        else:
            base = np.exp(-2.0 * np.linspace(-1, 1, 512) ** 2)
    else:
        base = np.exp(-2.0 * np.linspace(-1, 1, 512) ** 2)

    best = base / base.sum()
    bestC = _Cfft(best)
    print("start C=%.6f N=%d" % (bestC, best.size))

    # Multi-scale: refine at increasing resolutions
    schedule = [512, 768, 1024, 1536, 2048, 3072]
    for N in schedule:
        if time.process_time() > deadline:
            break
        h = _resample(best, N)
        if h.sum() <= 0:
            h = np.ones(N)
        h = h / h.sum()
        h, c = _polish(h, deadline, rng, step0=0.2, passes=5)
        if c < bestC - 1e-12:
            bestC, best = c, h.copy()
        h, c = _polish(h, deadline, rng, step0=0.06, passes=5)
        if c < bestC - 1e-12:
            bestC, best = c, h.copy()
        # small random perturbation + polish
        for _ in range(2):
            if time.process_time() > deadline:
                break
            cand = best * (1.0 + 0.06 * rng.standard_normal(best.size))
            cand = np.maximum(cand, 0.0)
            if cand.sum() <= 0:
                continue
            cand /= cand.sum()
            cand, cc = _polish(cand, deadline, rng, step0=0.05, passes=3)
            if cc < bestC - 1e-12:
                bestC, best = cc, cand.copy()
        print("N=%d C=%.6f cpu=%.1f" % (N, bestC, time.process_time() - t0))

    # Final intensive polish at highest resolution reached
    Nbest = best.size
    while time.process_time() < deadline:
        h, c = _polish(best, deadline, rng, step0=0.03, passes=3)
        if c < bestC - 1e-13:
            bestC, best = c, h.copy()
            print("improved C=%.6f cpu=%.1f" % (bestC, time.process_time() - t0))
        else:
            # random block perturbation
            h2 = best.copy()
            for _ in range(4):
                i = rng.integers(0, Nbest)
                w = rng.integers(1, max(2, Nbest // 20))
                j = min(Nbest, i + w)
                h2[i:j] *= np.exp(rng.normal(0, 0.05))
            if h2.sum() <= 0:
                break
            c2 = _Cfft(h2)
            if c2 < bestC - 1e-13:
                bestC, best = c2, h2.copy()
            else:
                break

    final_C = _C(best)
    print("best C=%.6f (exact %.6f) N=%d cpu=%.2f" %
          (bestC, final_C, best.size, time.process_time() - t0))
    return np.maximum(best, 0.0)

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution
from numpy.polynomial import chebyshev as C


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    N = h.size
    return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)


def _Cfft(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    n = h.size
    L = 2 * n - 1
    m = 1
    while m < L:
        m <<= 1
    f = np.fft.rfft(h, m)
    conv = np.fft.irfft(f * f, m)[:L]
    return 2.0 * n * np.max(conv) / (s * s)


def _conv(h):
    return np.convolve(h, h)


def _resample(s, N):
    s = np.asarray(s, dtype=float)
    if s.size == N:
        return s.copy()
    x_old = np.linspace(0, 1, s.size)
    x_new = np.linspace(0, 1, N)
    return np.interp(x_new, x_old, s)


def _near_frac(conv, frac=0.999):
    M = conv.max()
    return float(np.mean(conv >= frac * M))


def _refine(h, iters, deadline, rng, step0=0.2):
    n = h.size
    h = h.copy()
    c = _Cfft(h)
    step = step0
    while step > 1e-4 and time.process_time() < deadline:
        improved = False
        idxs = rng.permutation(n)
        for i in idxs:
            if time.process_time() > deadline:
                return h, c
            old = h[i]
            bl = old
            blc = c
            for mult in (1.0 + step, 1.0 - step):
                nv = old * mult
                if nv < 0:
                    nv = 0.0
                h[i] = nv
                cc = _Cfft(h)
                if cc < blc - 1e-13:
                    blc = cc
                    bl = nv
            h[i] = bl
            if blc < c - 1e-13:
                c = blc
                improved = True
        if not improved:
            step *= 0.5
    return h, c


def _plateau_obj(conv, s, n, lam, thresh=0.995):
    M = conv.max()
    mask = conv > thresh * M
    if mask.any():
        d = conv[mask] - M
        pen = float(np.dot(d, d))
    else:
        pen = 0.0
    return M + lam * pen / (s * s)


def _refine_plateau(h, deadline, rng, lam, step0=0.05, max_passes=4):
    n = h.size
    h = h.copy()
    s = h.sum()
    if s <= 0:
        return h, np.inf
    conv = np.convolve(h, h)
    obj = _plateau_obj(conv, s, n, lam)
    step = step0
    passes = 0
    while step > 1e-4 and passes < max_passes and time.process_time() < deadline:
        passes += 1
        improved = False
        idxs = rng.permutation(n)
        for i in idxs:
            if time.process_time() > deadline:
                return h, _Cfft(h)
            old = h[i]
            if old <= 0:
                continue
            best_v = old
            best_obj = obj
            best_conv = None
            best_s = s
            for mult in (1.0 + step, 1.0 - step):
                nv = old * mult
                if nv < 0:
                    nv = 0.0
                if nv == old:
                    continue
                h[i] = nv
                nc = np.convolve(h, h)
                h[i] = old
                ns = s - old + nv
                if ns <= 0:
                    continue
                no = _plateau_obj(nc, ns, n, lam)
                if no < best_obj - 1e-14:
                    best_obj = no
                    best_v = nv
                    best_conv = nc
                    best_s = ns
            if best_v != old:
                h[i] = best_v
                s = best_s
                conv = best_conv
                obj = best_obj
                improved = True
        if not improved:
            step *= 0.5
    return h, _Cfft(h)


def _block3_to_h(params, N):
    b1, b2, h2, h3 = params
    # breakpoints in [0,1]; heights h1=1
    x = np.linspace(0, 1, N, endpoint=False) + 0.5 / N
    h = np.empty(N)
    h[x < b1] = 1.0
    h[(x >= b1) & (x < b2)] = h2
    h[x >= b2] = h3
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(20240607)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            base = np.maximum(s, 0.0)
        else:
            base = np.ones(512)
    else:
        x = np.linspace(-1, 1, 512)
        base = np.exp(-3.0 * x * x)

    base = base / base.sum()
    best = base.copy()
    bestC = _C(best)
    print("start C = %.6f, N = %d" % (bestC, best.size))

    # ---- Global search over 3-block step at N=512 ----
    Nglob = 512

    def obj3(p):
        b1, b2, h2, h3 = p
        if not (0.0 < b1 < b2 < 1.0):
            return 10.0
        h = _block3_to_h((b1, b2, h2, h3), Nglob)
        if h.sum() <= 0:
            return 10.0
        return _Cfft(h)

    de_deadline = t0 + budget_seconds * 0.45
    best_param = None
    best_val = np.inf
    try:
        # budget DE by limiting maxiter; check time via callback
        def cb(xk, convergence=None):
            return time.process_time() > de_deadline

        res = differential_evolution(
            obj3,
            bounds=[(0.01, 0.98), (0.02, 0.99), (0.0, 5.0), (0.0, 5.0)],
            maxiter=200, popsize=20, tol=1e-8, seed=12345,
            polish=True, callback=cb, workers=1, updating='immediate'
        )
        best_param = res.x
        best_val = res.fun
        print("DE C=%.6f params=%s cpu=%.1f"
              % (best_val, np.round(best_param, 4), time.process_time() - t0))
    except Exception as e:
        print("DE failed:", e)

    if best_param is not None and np.isfinite(best_val):
        # resample to 768 and polish
        h3b = _block3_to_h(best_param, 768)
        h3b = np.maximum(h3b, 0.0)
        if h3b.sum() > 0:
            h3b = h3b / h3b.sum()
            h3b, c3 = _refine_plateau(h3b, deadline, rng, 10.0,
                                      step0=0.05, max_passes=3)
            h3b, c3 = _refine(h3b, 150, deadline, rng, 0.03)
            print("block3 polished C=%.6f cpu=%.1f"
                  % (c3, time.process_time() - t0))
            if c3 < bestC - 1e-10:
                bestC, best = c3, h3b.copy()

    # ---- Continue p0037-style polishing from best ----
    if time.process_time() < deadline:
        Nwork = max(best.size, 1024)
        if Nwork > 2048:
            Nwork = 2048
        h = _resample(best, Nwork)
        h = h / h.sum()
        for lam in [10.0, 100.0, 1000.0]:
            if time.process_time() > deadline:
                break
            h, c = _refine_plateau(h, deadline, rng, lam,
                                   step0=0.05, max_passes=3)
            h, c = _refine(h, 80, deadline, rng, 0.03)
            print("lam=%.0f C=%.6f cpu=%.1f"
                  % (lam, c, time.process_time() - t0))
            if c < bestC - 1e-10:
                bestC, best = c, h.copy()

    # Final resolution sweep
    for N in [768, 1024, 1536]:
        if time.process_time() > deadline:
            break
        h = _resample(best, N)
        h = h / h.sum()
        h, c = _refine(h, 120, deadline, rng, 0.05)
        if c < bestC - 1e-10:
            bestC, best = c, h.copy()
            print("N=%d C=%.6f cpu=%.1f"
                  % (N, bestC, time.process_time() - t0))

    conv = _conv(best)
    print("final C = %.6f, N = %d, near=%.4f, cpu %.2f s"
          % (bestC, best.size, _near_frac(conv, 0.999),
             time.process_time() - t0))
    return np.maximum(best, 0.0)

