                if time.process_time() > deadline:
                    return h, _Cfft(h)
                old = h[i]
                if old <= 0:
                    continue
                best_v = old
                best_obj = _topk_obj(conv, k) / (s * s)
                best_conv = None
                best_s = s
                # window affected by changing h[i]
                for mult in (1.0 + step, 1.0 - step):
                    nv = old * mult
                    if nv < 0:
                        nv = 0.0
                    delta = nv - old
                    if delta == 0.0:
                        continue
                    s2 = s + delta
                    if s2 <= 0:
                        continue
                    w = conv.copy()
                    a, b = i, i + n
                    w[a:b] += delta * h[0:n]
                    a, b = 0, n - i
                    w[a:b] += delta * h[i::-1][:b - a]
                    w[2 * i] += delta * delta
                    no = _topk_obj(w, k) / (s2 * s2)
                    if no < best_obj - 1e-14:
                        best_obj = no
                        best_v = nv
                        best_conv = w
                        best_s = s2
                if best_v != old:
                    h[i] = best_v
                    s = best_s
                    conv = best_conv
                    improved = True
            if not improved:
                step *= 0.5
                if step < 1e-4:
                    break
        return h, _Cfft(h)

    # ---- single-coordinate polish on true C (as in original) ----
    def polish(h, deadline, step0=0.15, passes=8):
        h = h.copy()
        n = h.size
        L = 2 * n - 1
        s = float(h.sum())
        if s <= 0:
            return h, np.inf
        conv = np.convolve(h, h)
        step = step0
        for _ in range(passes):
            if time.process_time() > deadline:
                break
            improved = False
            order = rng.permutation(n)
            for i in order:
                if time.process_time() > deadline:
                    return h, _Cfft(h)
                old = h[i]
                if old <= 0:
                    continue
                wlo = 0
                whi = min(L, max(i + n, n - i))
                base_max = conv.max()
                outside_max = max(conv[:wlo].max() if wlo > 0 else -np.inf,
                                  conv[whi:].max() if whi < L else -np.inf)
                best_v = old
                best_num = base_max
                best_conv = None
                best_s = s
                for mult in (1.0 + step, 1.0 - step):
                    nv = old * mult
                    if nv < 0:
                        nv = 0.0
                    delta = nv - old
                    if delta == 0.0:
                        continue
                    s2 = s + delta
                    if s2 <= 0:
                        continue
                    w = conv[wlo:whi].copy()
                    a = max(wlo, i)
                    b = min(whi, i + n)
                    if b > a:
                        w[a - wlo:b - wlo] += delta * h[a - i:b - i]
                    a = max(wlo, 0)
                    b = min(whi, n - i)
                    if b > a:
                        w[a - wlo:b - wlo] += delta * h[(i - np.arange(a, b))]
                    if wlo <= 2 * i < whi:
                        w[2 * i - wlo] += delta * delta
                    new_max = max(outside_max, w.max()) if (wlo > 0 or whi < L) else w.max()
                    cc = new_max / (s2 * s2)
                    cbest = best_num / (best_s * best_s)
                    if cc < cbest - 1e-15:
                        best_num = new_max
                        best_s = s2
                        best_v = nv
                        best_conv = (wlo, whi, w)
                if best_v != old:
                    delta = best_v - old
                    h[i] = best_v
                    s = best_s
                    lo, hi, w = best_conv
                    conv[lo:hi] = w
                    improved = True
            if not improved:
                step *= 0.5
                if step < 1e-4:
                    break
        return h, _Cfft(h)

    schedule = [512, 1024, 2048, 4096]
    for N in schedule:
        if time.process_time() > deadline:
            break
        h = _resample(best, N)
        if h.sum() <= 0:
            h = np.ones(N)
        h = h / h.sum()
        # top-k polish first (flatten plateau), k_frac decreasing
        for kf in (0.05, 0.02, 0.01):
            if time.process_time() > deadline:
                break
            h, c = polish_topk(h, deadline, k_frac=kf, step0=0.1, passes=3)
        h, c = polish(h, deadline, step0=0.2, passes=6)
        if c < bestC - 1e-12:
            bestC, best = c, h.copy()
        h, c = polish(h, deadline, step0=0.06, passes=6)
        if c < bestC - 1e-12:
            bestC, best = c, h.copy()
        print("N=%d C=%.6f cpu=%.1f" % (N, bestC, time.process_time() - t0))

    # ---- targeted plateau polish: optimize sum of top-k at final N ----
    Nbest = best.size
    if time.process_time() < deadline:
        h = best.copy()
        h, c = polish_topk(h, deadline, k_frac=0.005, step0=0.05, passes=6)
        h, c = polish(h, deadline, step0=0.02, passes=8)
        if c < bestC - 1e-12:
            bestC, best = c, h.copy()
        print("plateau polish C=%.6f cpu=%.1f" % (bestC, time.process_time() - t0))

    # ---- random block perturbations with full re-polish ----
    while time.process_time() < deadline:
        h2 = best.copy()
        for _ in range(4):
            i = rng.integers(0, Nbest)
            w = int(rng.integers(1, max(2, Nbest // 20)))
            j = min(Nbest, i + w)
            h2[i:j] *= np.exp(rng.normal(0, 0.08))
        h2 = np.maximum(h2, 0.0)
        if h2.sum() <= 0:
            continue
        h2 = h2 / h2.sum()
        h2, c2 = polish(h2, deadline, step0=0.05, passes=4)
        if c2 < bestC - 1e-12:
            bestC, best = c2, h2.copy()
            print("perturbed C=%.6f cpu=%.1f" % (bestC, time.process_time() - t0))

    final_C = _C(best)
    print("best C = %.6f (exact %.6f), N = %d, cpu %.2f s" %
          (bestC, final_C, best.size, time.process_time() - t0))
    return best

import numpy as np
import time


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    n = h.size
    return 2.0 * n * np.max(np.convolve(h, h)) / (s * s)


def _fft_conv(h):
    n = h.size
    L = 2 * n - 1
    m = 1
    while m < L:
        m <<= 1
    F = np.fft.rfft(h, m)
    return np.fft.irfft(F * F, m)[:L]


def _Cfft(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    n = h.size
    return 2.0 * n * np.max(_fft_conv(h)) / (s * s)


def _resample(s, N):
    s = np.asarray(s, dtype=float)
    if s.size == N:
        return s.copy()
    x_old = np.linspace(0.0, 1.0, s.size)
    x_new = np.linspace(0.0, 1.0, N)
    return np.interp(x_new, x_old, s)


def _refine(h, iters, deadline, rng, step0=0.15):
    n = h.size
    h = h.copy()
    c = _Cfft(h)
    step = step0
    while step > 1e-4 and time.process_time() < deadline:
        improved = False
        idxs = rng.permutation(n)
        for i in idxs:
            if time.process_time() > deadline:
                return h, c
            old = h[i]
            bl = old
            blc = c
            for mult in (1.0 + step, 1.0 - step):
                nv = old * mult
                if nv < 0:
                    nv = 0.0
                h[i] = nv
                cc = _Cfft(h)
                if cc < blc - 1e-13:
                    blc = cc
                    bl = nv
            h[i] = bl
            if blc < c - 1e-13:
                c = blc
                improved = True
        if not improved:
            step *= 0.5
    return h, c


def _plateau_obj(conv, s, lam, thresh=0.998):
    M = conv.max()
    mask = conv > thresh * M
    d = conv[mask] - M
    pen = float(np.dot(d, d))
    return M + lam * pen / (s * s)


def _refine_plateau(h, deadline, rng, lam, step0=0.05, max_passes=4, thresh=0.998):
    n = h.size
    h = h.copy()
    s = h.sum()
    if s <= 0:
        return h, np.inf
    conv = np.convolve(h, h)
    obj = _plateau_obj(conv, s, lam, thresh)
    step = step0
    passes = 0
    while step > 1e-4 and passes < max_passes and time.process_time() < deadline:
        passes += 1
        improved = False
        idxs = rng.permutation(n)
        for i in idxs:
            if time.process_time() > deadline:
                return h, _Cfft(h)
            old = h[i]
            if old <= 0:
                continue
            best_v = old
            best_obj = obj
            best_conv = None
            best_s = s
            for mult in (1.0 + step, 1.0 - step):
                nv = old * mult
                if nv < 0:
                    nv = 0.0
                if nv == old:
                    continue
                h[i] = nv
                nc = np.convolve(h, h)
                h[i] = old
                ns = s - old + nv
                if ns <= 0:
                    continue
                no = _plateau_obj(nc, ns, lam, thresh)
                if no < best_obj - 1e-14:
                    best_obj = no
                    best_v = nv
                    best_conv = nc
                    best_s = ns
            if best_v != old:
                h[i] = best_v
                s = best_s
                conv = best_conv
                obj = best_obj
                improved = True
        if not improved:
            step *= 0.5
    return h, _Cfft(h)


def _sweep_incremental(h, deadline, rng, step0=0.05, min_step=1e-4, max_sweeps=25):
    """Coordinate descent with O(n) incremental conv updates."""
    n = h.size
    h = h.copy()
    conv = np.convolve(h, h)
    s = h.sum()
    if s <= 0:
        return h, np.inf
    C = 2.0 * n * conv.max() / (s * s)
    step = step0
    sweeps = 0
    while step > min_step and sweeps < max_sweeps:
        if time.process_time() > deadline:
            break
        sweeps += 1
        improved = False
        idxs = rng.permutation(n)
        for i in idxs:
            if time.process_time() > deadline:
                break
            old = h[i]
            if old <= 0:
                continue
            best_v = old
            best_C = C
            best_conv = None
            best_s = s
            for mult in (1.0 + step, 1.0 - step):
                nv = old * mult
                if nv < 0:
                    nv = 0.0
                if nv == old:
                    continue
                delta = nv - old
                seg = conv[i:i + n] + delta * h
                ns = s + delta
                if ns <= 0:
                    continue
                m1 = seg.max()
                if i > 0:
                    m0 = conv[:i].max()
                else:
                    m0 = -np.inf
                if i + n < conv.size:
                    m2 = conv[i + n:].max()
                else:
                    m2 = -np.inf
                newmax = max(m0, m1, m2)
                nC = 2.0 * n * newmax / (ns * ns)
                if nC < best_C - 1e-13:
                    best_C = nC
                    best_v = nv
                    best_conv = seg
                    best_s = ns
            if best_v != old:
                h[i] = best_v
                conv[i:i + n] = best_conv
                s = best_s
                C = best_C
                improved = True
        if not improved:
            step *= 0.5
    return h, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(20240607)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
