def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 0.5

    best = None
    bestC = np.inf

    # Consider the start if it already beats the constant baseline.
    if start is not None:
        h0 = np.asarray(start, dtype=float).ravel()
        if h0.size > 0 and np.all(np.isfinite(h0)) and h0.sum() > 0:
            c0 = _C(h0)
            if c0 < 2.0:
                best = h0.copy()
                bestC = c0

    N = 40
    rng = np.random.default_rng(12345)

    h = np.ones(N)
    hC = _C(h)
    if hC < bestC:
        best, bestC = h.copy(), hC

    iters = 5000
    for it in range(iters):
        if time.process_time() - t0 > deadline:
            break
        cand = h.copy()
        k = rng.integers(1, 4)
        idx = rng.integers(0, N, size=k)
        factors = rng.uniform(0.5, 1.5, size=k)
        cand[idx] *= factors
        np.clip(cand, 0.0, None, out=cand)
        if cand.sum() <= 0:
            continue
        cC = _C(cand)
        if cC < hC:
            h, hC = cand, cC
            if hC < bestC:
                best, bestC = h.copy(), hC
        # Restart from random nonnegative array every 500 iterations if no recent improvement.
        if (it + 1) % 500 == 0:
            # Check whether we improved since last checkpoint by comparing to best.
            if hC >= bestC:
                h = rng.random(N)
                hC = _C(h)
                if hC < bestC:
                    best, bestC = h.copy(), hC

    if best is None:
        best = np.ones(N)
    return best

