    N = 500
    x = np.linspace(-0.25, 0.25, N)

    best_h = None
    best_C = np.inf

    def evalC(h):
        s = h.sum()
        if s <= 0:
            return np.inf
        return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)

    # Family (a): exponential
    for a in np.linspace(0.0, 20.0, 201):
        h = np.exp(-a * x)
