import numpy as np
import time
from scipy.optimize import minimize
from scipy.special import logsumexp


def _C(h):
    N = len(h)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 200
    beta = 2000.0
    rng = np.random.default_rng(12345)

    def make_h(v):
        z = v - v.max()
        e = np.exp(z)
        return e / e.sum()

    def objective(v):
        h = make_h(v)
        conv = np.convolve(h, h)
        return logsumexp(beta * conv) / beta

    best_h = None
    best_C = np.inf

    # include start if provided (resampled to N)
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            # resample to N by interpolation
            x_old = np.linspace(0, 1, s.size)
            x_new = np.linspace(0, 1, N)
            h0 = np.interp(x_new, x_old, s)
            h0 = np.maximum(h0, 1e-12)
            c0 = _C(h0)
            if c0 < best_C:
                best_C = c0
                best_h = h0

    n_restarts = 5
    for r in range(n_restarts):
        if time.process_time() - t0 > budget_seconds * 0.85:
            break
        if r == 0:
            v0 = np.zeros(N)
        else:
            v0 = rng.normal(0, 0.5, N)
        try:
            res = minimize(objective, v0, method='L-BFGS-B',
                           options={'maxiter': 500})
            h = make_h(res.x)
            c = _C(h)
            if c < best_C:
                best_C = c
                best_h = h
        except Exception:
            pass

    if best_h is None:
        best_h = np.ones(N)

    print(f"best C = {best_C:.6f}, N = {N}")
    return best_h

import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    def score(h):
        h = np.asarray(h, dtype=float)
        s = h.sum()
        if s <= 0:
            return np.inf
        return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)

    # Start point
    if start is not None:
        h = np.asarray(start, dtype=float).ravel().copy()
        if h.size > 30000:
            h = h[:30000]
        if h.size == 0 or h.sum() <= 0:
            h = np.ones(50)
    else:
        h = np.ones(50)

    best = h.copy()
    best_c = score(best)

    # Structured candidates (smooth bumps), plus scaled versions
    candidates = []
    for N in [50, 100, 200, 400, 800, 1600, 3200, 6400]:
        n = np.arange(N) + 0.5
        x = (n / N) * 2.0 - 1.0
        candidates.append(np.maximum(0.0, 1.0 - x * x) + 1e-6)
        candidates.append(np.cos(np.pi * x / 2.0) ** 2 + 1e-6)
        candidates.append(np.maximum(0.0, 1.0 - np.abs(x)) + 1e-6)

    for cand in candidates:
        c = score(cand)
        if c < best_c:
            best_c = c
            best = cand.copy()

    rng = np.random.default_rng(12345)

    def optimize(h, iterations, step_scale):
        nonlocal best, best_c
        h = h.copy()
        cur_c = score(h)
        n = h.size
        for it in range(iterations):
            if time.process_time() > deadline:
                break
            # occasionally perturb a block, usually a single entry
            if rng.random() < 0.15 and n > 4:
                k = rng.integers(2, max(3, min(8, n)))
                idx = rng.integers(0, n, size=k)
                old = h[idx].copy()
                h[idx] *= np.exp(rng.normal(0.0, step_scale, size=k))
                new_c = score(h)
                if new_c < cur_c:
                    cur_c = new_c
                else:
                    h[idx] = old
            else:
                i = rng.integers(0, n)
                old = h[i]
                h[i] = old * np.exp(rng.normal(0.0, step_scale))
                new_c = score(h)
                if new_c < cur_c:
                    cur_c = new_c
                else:
                    h[i] = old
        if cur_c < best_c:
            best_c = cur_c
            best = h.copy()
        return h, cur_c

    # Multi-resolution: optimize at several N with decreasing step sizes
    for N in [50, 100, 200, 400, 800]:
        src = np.asarray(best, dtype=float)
        xs = (np.arange(src.size) + 0.5) / src.size
        xn = (np.arange(N) + 0.5) / N
        h = np.interp(xn, xs, src)
