def construct(budget_seconds, start):
    t0 = time.process_time()
    # leave generous margin
    deadline = t0 + budget_seconds * 0.75

    def score(h):
        s = h.sum()
        if s <= 0:
            return np.inf
        return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)

    # Analytic subgradient of C w.r.t. h at the argmax knot of the autoconvolution.
    # conv[k] = sum_i h_i h_{k-i}; dM/dh_p = 2 h_{k-p} (symmetric), correctly
    # accounting for the diagonal.  dC/dh_p = 2n (dM/dh_p * s - 2 M) / s^3.
    def grad(h, k=None):
        n = h.size
        s = h.sum()
        conv = np.convolve(h, h)
        if k is None:
            k = int(np.argmax(conv))
        M = conv[k]
        g = np.zeros(n)
        lo = max(0, k - n + 1)
        hi = min(n - 1, k)
        # dM/dh_p = h_{k-p} + h_{k-(k-p)} = 2 h_{k-p}  (valid since k-p in range)
        for p in range(lo, hi + 1):
            g[p] = 2.0 * h[k - p]
        dC = 2.0 * n * (g * s - 2.0 * M) / (s ** 3)
        return dC, M, s, k

    # ---- start ----
    if start is not None:
        h0 = np.asarray(start, dtype=float).ravel().copy()
        if h0.size > 30000:
            h0 = h0[:30000]
        if h0.size == 0 or h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        h0 = np.ones(50)

    best = h0.copy()
    best_c = score(best)

    rng = np.random.default_rng(2024)

    # candidates only if start is missing/weak
    if start is None:
        for N in [100, 200, 400, 800]:
            n = np.arange(N) + 0.5
            x = (n / N) * 2.0 - 1.0
            for cand in [np.maximum(0.0, 1.0 - x * x) + 1e-6,
                         np.cos(np.pi * x / 2.0) ** 2 + 1e-6]:
                c = score(cand)
                if c < best_c:
                    best_c = c
                    best = cand.copy()

    def project(h):
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones_like(h)
        return h / s

    # Fast projected subgradient descent on the argmax knot.
    def subgrad_descent(h, iters, lr0):
        h = project(np.asarray(h, dtype=float))
        cur = score(h)
        lr = lr0
        for it in range(iters):
            if time.process_time() > deadline:
                break
            dC, M, s, k = grad(h)
            gn = np.linalg.norm(dC)
            if gn < 1e-14:
                break
            step = lr * dC / gn
            # scale step to h magnitude
            h2 = project(h - step * (h.mean() + 1e-12))
            c2 = score(h2)
            if c2 < cur - 1e-15:
                h = h2
                cur = c2
                lr *= 1.05
            else:
                lr *= 0.5
                if lr < 1e-12:
                    break
        return h, cur

    # Coordinate descent with multiplicative factor; batched over many
    # coordinates at once via a vectorised perturbation-and-test.
    def coord_search(h, iterations, step_scale):
        h = h.copy()
        cur = score(h)
        n = h.size
        for _ in range(iterations):
            if time.process_time() > deadline:
                break
            i = rng.integers(0, n)
            old = h[i]
            h[i] = old * np.exp(rng.normal(0.0, step_scale))
            nc = score(h)
            if nc < cur:
                cur = nc
            else:
                h[i] = old
        return h, cur

    # Multi-resolution: refine at increasing N, using subgrad descent and
    # coordinate search.  Keep the best overall.
    for N in [200, 400, 800, 1600]:
        if time.process_time() > deadline:
            break
        src = np.asarray(best, dtype=float)
        xs = (np.arange(src.size) + 0.5) / src.size
        xn = (np.arange(N) + 0.5) / N
