        if c < best_c:
            best_c = c
            best = h.copy()

        for ss, it in [(0.2, 3000), (0.06, 5000)]:
            if time.process_time() > deadline:
                break
            h, c = coord_search(h, it, ss)
        if c < best_c:
            best_c = c
            best = h.copy()

    # Final fine refinement on the best solution.
    h = np.asarray(best, dtype=float).copy()
    h, c = subgrad_descent(h, 400, 0.3)
    if c < best_c:
        best_c = c
        best = h.copy()
    for ss, it in [(0.02, 8000), (0.006, 10000)]:
        if time.process_time() > deadline:
            break
        h, c = coord_search(h, it, ss)
        if c < best_c:
            best_c = c
            best = h.copy()

    return np.asarray(best, dtype=float)

