    def resample(src, N):
        src = np.asarray(src, dtype=float)
        xs = (np.arange(src.size) + 0.5) / src.size
        xn = (np.arange(N) + 0.5) / N
        return np.maximum(np.interp(xn, xs, src), 1e-12)

    def refine(h, iters, step_scale):
        h = h.copy()
        cur_c = score(h)
        n = h.size
        i = 0
        for _ in range(iters):
            if time.process_time() > deadline:
                break
            old = h[i]
            h[i] = old * np.exp(rng.normal(0.0, step_scale))
            nc = score(h)
            if nc < cur_c:
                cur_c = nc
            else:
                h[i] = old
            i += 1
            if i >= n:
                i = 0
        return h, cur_c

    # Multi-resolution hill-climb
    for N in [200, 400, 800, 1600, 3200]:
        if time.process_time() > deadline:
            break
        h = resample(best, N)
        for step_scale, iters in [(0.25, 4 * N), (0.08, 6 * N), (0.03, 8 * N)]:
            if time.process_time() > deadline:
                break
            h, c = refine(h, iters, step_scale)
            if c < best_c:
                best_c = c
                best = h.copy()

    # Fine refinement at best N
    h = np.asarray(best, dtype=float)
    for step_scale, iters in [(0.015, 25 * h.size), (0.005, 25 * h.size),
                              (0.002, 25 * h.size)]:
        if time.process_time() > deadline:
            break
        h, c = refine(h, iters, step_scale)
        if c < best_c:
            best_c = c
            best = h.copy()

    return np.asarray(best, dtype=float)

import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    def score(h):
        h = np.asarray(h, dtype=float)
        s = h.sum()
        if s <= 0:
            return np.inf
        return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)

    if start is not None:
        h = np.asarray(start, dtype=float).ravel().copy()
        if h.size > 30000:
            h = h[:30000]
        if h.size == 0 or h.sum() <= 0:
            h = np.ones(50)
    else:
        h = np.ones(50)

    best = h.copy()
    best_c = score(best)
    rng = np.random.default_rng(12345)

    def resample(src, N):
        src = np.asarray(src, dtype=float)
        xs = (np.arange(src.size) + 0.5) / src.size
        xn = (np.arange(N) + 0.5) / N
        return np.maximum(np.interp(xn, xs, src), 1e-9)

    def refine(h, iterations, step_scale):
        """Gradient-free multiplicative hill-climb on random coordinates."""
        h = h.copy()
        cur_c = score(h)
        n = h.size
        for it in range(iterations):
            if (it & 255) == 0 and time.process_time() > deadline:
                break
            i = rng.integers(0, n)
            old = h[i]
            h[i] = old * np.exp(rng.normal(0.0, step_scale))
            new_c = score(h)
            if new_c < cur_c:
                cur_c = new_c
            else:
                h[i] = old
        return h, cur_c

    # Multi-resolution hill-climb
    for N in [100, 200, 400, 800, 1600]:
        if time.process_time() > deadline:
            break
        h = resample(best, N)
        for step_scale, iters in [(0.3, 3 * N), (0.1, 5 * N), (0.04, 8 * N)]:
            if time.process_time() > deadline:
                break
            h, c = refine(h, iters, step_scale)
            if c < best_c:
                best_c = c
                best = h.copy()

    # Final fine sweep at current best N
    h = np.asarray(best, dtype=float)
    for step_scale, iters in [(0.02, 20 * h.size), (0.007, 20 * h.size)]:
        if time.process_time() > deadline:
            break
        h, c = refine(h, iters, step_scale)
        if c < best_c:
            best_c = c
            best = h.copy()

    return np.asarray(best, dtype=float)
